SELECT

FROM TC_BUSINESS_RULE


        AND RULE_CODE = #{ruleCode}


        AND RULE_NAME LIKE CONCAT('%', #{ruleName}, '%')


        AND RULE_TYPE = #{ruleType}


        AND RULE_CATEGORY = #{ruleCategory}


        AND BUSINESS_DOMAIN = #{businessDomain}


        AND IS_ACTIVE = #{isActive}


        AND STATUS = #{status}


ORDER BY CREATE_TIME DESC

SELECT

FROM TC_BUSINESS_RULE
WHERE IS_ACTIVE = '1'

    AND RULE_TYPE = #{ruleType}


    AND BUSINESS_DOMAIN = #{businessDomain}

ORDER BY EXECUTION_ORDER ASC, CREATE_TIME DESC

SELECT

FROM TC_BUSINESS_RULE


        AND RULE_TYPE = #{ruleType}


        AND BUSINESS_DOMAIN = #{businessDomain}


ORDER BY EXECUTION_ORDER ASC, CREATE_TIME DESC

SELECT
FROM TC_BUSINESS_RULE WHERE IS_ACTIVE = '1' AND STATUS = '1' AND (EFFECTIVE_DATE IS NULL OR EFFECTIVE_DATE <= #{currentDate}) AND (EXPIRE_DATE IS NULL OR EXPIRE_DATE >= #{currentDate})
AND RULE_TYPE = #{ruleType}
AND BUSINESS_DOMAIN = #{businessDomain}
ORDER BY EXECUTION_ORDER ASC, CREATE_TIME DESC

SELECT COUNT(1)
FROM TC_BUSINESS_RULE
WHERE RULE_CODE = #{ruleCode}

    AND ID != #{excludeId}

SELECT COUNT(1)
FROM TC_BUSINESS_RULE
WHERE 1=1

    AND RULE_TYPE = #{ruleType}


    AND BUSINESS_DOMAIN = #{businessDomain}
